<?php $all=products();$cats=categories();$edit=filter_var($_GET['edit']??null,FILTER_VALIDATE_INT);$editing=null;foreach($all as $p)if((int)$p['id']===$edit)$editing=$p;$lowCount=count(array_filter($all,fn($p)=>(int)$p['status']===1&&(int)$p['stock']<=10));?>
<div class="page-heading"><div><p class="eyebrow">KATALOG KAFE</p><h1>Menu & stok</h1><p class="subheading">Atur harga, kategori, dan ketersediaan menu.</p></div></div><div class="admin-layout"><section class="panel"><div class="panel-heading"><div><h2>Daftar menu</h2><p><?= count($all) ?> menu · <?= $lowCount ?> stok menipis</p></div><span class="status pending">Ambang stok rendah ≤ 10</span></div><div class="table-scroll"><table><thead><tr><th>Kode / nama menu</th><th>Kategori</th><th>Harga jual</th><th>Modal</th><th>Stok</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($all as $p):?><tr><td><strong><?= e($p['name']) ?></strong><small class="table-sub"><?= e($p['code']) ?></small></td><td><?= e($p['category_name']) ?></td><td><?= rupiah($p['price']) ?></td><td><?= rupiah($p['cost_price']) ?></td><td><span class="<?= $p['stock']<=10?'low-stock':'' ?>"><?= (int)$p['stock'] ?> <?= e($p['unit']) ?></span></td><td><span class="status <?= $p['status']?'done':'cancelled' ?>"><?= $p['status']?'Aktif':'Nonaktif' ?></span></td><td class="menu-actions"><a href="index.php?page=menu&edit=<?= (int)$p['id'] ?>">Ubah</a><form method="post"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="toggle-product"><input type="hidden" name="id" value="<?= (int)$p['id'] ?>"><button class="link-button" type="submit"><?= $p['status']?'Nonaktifkan':'Aktifkan' ?></button></form></td></tr><?php endforeach;?></tbody></table></div></section><aside class="admin-forms"><section class="panel compact-form"><h2><?= $editing?'Ubah menu':'Tambah menu' ?></h2><p>Data tersimpan langsung ke katalog.</p><form method="post" class="stack-form"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="save-product"><input type="hidden" name="id" value="<?= (int)($editing['id']??0) ?>"><label>Nama menu<input name="name" value="<?= e($editing['name']??'') ?>" maxlength="100" required></label><label>Kode menu<input name="code" value="<?= e($editing['code']??'') ?>" maxlength="30" required></label><label>Kategori<select name="category_id" required><?php foreach($cats as $c):?><option value="<?= (int)$c['id'] ?>" <?= (int)($editing['category_id']??0)===(int)$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach;?></select></label><div class="form-grid"><label>Harga jual<input name="price" type="number" min="0" step="500" value="<?= e($editing['price']??'') ?>" required></label><label>Harga pokok<input name="cost" type="number" min="0" step="500" value="<?= e($editing['cost_price']??0) ?>" required></label></div><div class="form-grid"><label>Stok<input name="stock" type="number" min="0" value="<?= e($editing['stock']??0) ?>" required></label><label>Satuan<input name="unit" value="<?= e($editing['unit']??'porsi') ?>" maxlength="20" required></label></div><button class="button primary full" type="submit"><?= $editing?'Simpan perubahan':'Tambah ke menu' ?></button><?php if($editing):?><a class="cancel-link" href="index.php?page=menu">Batal mengubah</a><?php endif;?></form></section><section class="panel compact-form"><h2>Kategori baru</h2><p>Tambahkan kelompok untuk laporan.</p><form method="post" class="inline-category"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="save-category"><label class="sr-only" for="category-name">Nama kategori</label><input id="category-name" name="category_name" placeholder="Contoh: Pastry" maxlength="70" required><button class="button quiet" type="submit">Tambah</button></form></section></aside></div>
